# PanelGuard Steps 3-4 — the Python Keras twin of every JavaScript cell, run end to end (generated by tools/tests/twin_build.mjs).
# Preamble = the Step 1-2 notebook state: X, y, idx_train, idx_val (Step 1) and p_val (Step 2 baseline scores).
import os, json, time
os.environ['TF_CPP_MIN_LOG_LEVEL'] = '3'
import numpy as np
import keras
from sklearn.model_selection import train_test_split
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')
X = np.fromfile(os.path.join(ROOT, 'tools/ref/cells64.u8'), dtype=np.uint8).reshape(2624, 64, 64)
rows = json.load(open(os.path.join(ROOT, 'site/data/labels.json')))['rows']
prob = np.array([r[1] for r in rows]); kind = np.array([r[2] for r in rows]); y = (prob >= 0.5).astype(int)
idx = np.arange(len(y))
idx_train, idx_rest = train_test_split(idx, test_size=0.4, stratify=y, random_state=42)
idx_val, idx_test = train_test_split(idx_rest, test_size=0.5, stratify=y[idx_rest], random_state=42)
p_val = np.load(os.path.join(ROOT, 'tools/research/svc_val.npy'))   # Step 2 SVC validation scores (same pipeline as 2a/2b)
keras.utils.set_random_seed(int(os.environ.get('SEED', '0')))
T0 = time.time()

# ===== 3a Shape the photos =====
import numpy as np
import keras
from keras import layers

# [photos, rows, columns, channels], floats 0..1
X4 = X.reshape(2624, 64, 64, 1).astype('float32') / 255.0

x_train, y_train = X4[idx_train], y[idx_train].astype('float32')
x_val, y_val = X4[idx_val], y[idx_val]
print('X4', X4.shape, '  x_train', x_train.shape, '  x_val', x_val.shape)
print('smallest', X4.min(), '  largest', X4.max())

# ===== 3c Build the network =====
model = keras.Sequential()
model.add(keras.Input(shape=(64, 64, 1)))

for filters in [16, 32, 64, 128]:
    model.add(layers.Conv2D(filters, 3, padding='same', use_bias=False))
    model.add(layers.BatchNormalization())
    model.add(layers.Activation('relu'))
    model.add(layers.MaxPooling2D(2))

model.add(layers.GlobalAveragePooling2D())
model.add(layers.Dropout(0.3))
model.add(layers.Dense(1, activation='sigmoid'))

model.summary()

# ===== 3d Make more photos for free =====
rng = np.random.default_rng(0)

def flip_some(batch):
    n = len(batch)
    lr = rng.random(n) < 0.5
    out = np.where(lr[:, None, None, None], np.flip(batch, axis=2), batch)   # left-right
    ud = rng.random(n) < 0.5
    out = np.where(ud[:, None, None, None], np.flip(out, axis=1), out)       # up-down
    return out

demo = flip_some(x_train[:8])
print('demo batch', demo.shape)

# ===== 3e Train it =====
from sklearn.metrics import roc_auc_score

model.compile(optimizer=keras.optimizers.Adam(0.001), loss='binary_crossentropy')

n_def = int(y_train.sum())
n_ok = len(y_train) - n_def
class_weight = {0: len(y_train) / (2 * n_ok), 1: len(y_train) / (2 * n_def)}

EPOCHS = 30
best_auc, best_epoch, best_weights = -1, 0, None
for epoch in range(1, EPOCHS + 1):
    x_aug = flip_some(x_train)
    hist = model.fit(x_aug, y_train, epochs=1, batch_size=32, shuffle=True, class_weight=class_weight, verbose=0)
    p = model.predict(x_val, batch_size=128, verbose=0).ravel()
    auc = roc_auc_score(y_val, p)
    print(f'epoch {epoch:2d}  train loss {hist.history["loss"][0]:.3f}  validation ranking score {auc:.3f}')
    if auc > best_auc:
        best_auc, best_epoch, best_weights = auc, epoch, model.get_weights()
model.set_weights(best_weights)
print('best epoch:', best_epoch, '  validation ranking score:', round(best_auc, 3))

# ===== 3f Score it and blend it =====
from sklearn.metrics import precision_recall_curve

def false_alarm_at_95(y_true, score):
    pr, rc, cut = precision_recall_curve(y_true, score)
    c = cut[rc[:-1] >= 0.95].max()
    stop = score >= c
    return float((stop & (y_true == 0)).sum() / (y_true == 0).sum())

p_cnn = model.predict(x_val, batch_size=128, verbose=0).ravel()
p_svc = p_val                     # Step 2 scores, same cells, same order

best_w, best_far = 0, 1
for k in range(11):
    w = k / 10
    blend = w * p_cnn + (1 - w) * p_svc
    far = false_alarm_at_95(y_val, blend)
    if far < best_far:
        best_far, best_w = far, w
p_blend = best_w * p_cnn + (1 - best_w) * p_svc
print('CNN weight:', best_w, '  false-alarm rate at 95% recall:', round(best_far, 3))

# ===== 3g Two gates, not one =====
def_scores = np.sort(p_blend[y_val == 1])
low = def_scores[int(np.floor(0.05 * len(def_scores)))]

order = np.argsort(-p_blend)                          # highest first
caught = np.cumsum(y_val[order])
share_real = caught / np.arange(1, len(order) + 1)
ok = np.where(share_real >= 0.95)[0]
high = p_blend[order[ok.max()]] if len(ok) else np.inf

auto_pass = p_blend < low
auto_stop = p_blend >= max(high, low)
person = ~auto_pass & ~auto_stop
print(f'low gate {low:.3f}   high gate {high:.3f}')
print('defects passed by mistake:', int((auto_pass & (y_val == 1)).sum()), 'of', int((y_val == 1).sum()))
print(f'per 1,000 cells: auto-pass {1000 * auto_pass.mean():.0f}   person {1000 * person.mean():.0f}   auto-stop {1000 * auto_stop.mean():.0f}')

# ===== 4b The cover-up test =====
SIZE, STEP = 8, 4
N = (64 - SIZE) // STEP + 1                            # 15 spots across, 15 down

def gray_patch(img, r, c, size):
    out = img.copy()
    out[r:r + size, c:c + size] = img.mean()
    return out

def cover_up(img):                                     # img: (64, 64, 1)
    base = float(model.predict(img[None], verbose=0)[0, 0])
    covered = np.stack([gray_patch(img, r * STEP, c * STEP, SIZE) for r in range(N) for c in range(N)])
    return base - model.predict(covered, verbose=0).ravel()

PAINT_CELLS = [496, 1088, 379]
val_ids = [rows[i][0] for i in idx_val]
cover_map = cover_up(x_val[val_ids.index(PAINT_CELLS[0])])
print('spots:', cover_map.size, '  biggest drop:', round(float(cover_map.max()), 3))

# ===== 4c Ask the network directly =====
import tensorflow as tf

L = model.layers
acts = [l for l in L if isinstance(l, layers.Activation)]   # the ReLU after each block
cut = L.index(acts[2])                                       # block 3 (count from 0)
front, back = L[:cut + 1], L[cut + 1:]

def run(ls, x):
    for l in ls:
        x = l(x, training=False)
    return x

def grad_cam(img):                                    # img (64, 64, 1)  ->  map (16, 16)
    A = run(front, tf.constant(img[None]))             # block-3 feature maps (1, 16, 16, 64)
    with tf.GradientTape() as tape:
        tape.watch(A)
        s = tf.reduce_sum(run(back, A))
    g = tape.gradient(s, A)                            # how much each value pushes the score up
    w = tf.reduce_mean(g, axis=(0, 1, 2))              # one weight per feature map
    cam = tf.reduce_sum(A * w, axis=-1)[0]             # weighted sum of the 64 maps
    return tf.nn.relu(cam).numpy()                     # keep only what pushes towards "defect"

cam0 = grad_cam(x_val[val_ids.index(PAINT_CELLS[0])])
print('Grad-CAM grid:', cam0.shape)

# ===== 4d Is the heat map honest? =====
K = round(0.1 * 4096)                                  # 10% of the 4,096 pixels
def_idx = np.where(y_val == 1)[0]
rng = np.random.default_rng(0)
hot_imgs, rand_imgs = [], []
for i in def_idx:
    img = x_val[i]
    cam = tf.image.resize(grad_cam(img)[..., None], (64, 64), method='bilinear').numpy().ravel()
    hot = np.argsort(-cam)[:K]                         # hottest pixels first
    rnd = rng.choice(4096, K, replace=False)
    a = img.ravel().copy(); a[hot] = img.mean(); hot_imgs.append(a.reshape(64, 64, 1))
    b = img.ravel().copy(); b[rnd] = img.mean(); rand_imgs.append(b.reshape(64, 64, 1))
s0 = model.predict(x_val[def_idx], verbose=0).ravel()
drop_hot = float((s0 - model.predict(np.array(hot_imgs), verbose=0).ravel()).mean())
drop_rand = float((s0 - model.predict(np.array(rand_imgs), verbose=0).ravel()).mean())
print('defects:', len(def_idx), '  drop (hottest 10%):', round(drop_hot, 3), '  drop (random 10%):', round(drop_rand, 3))

# ===== 4e Where does it fail? =====
kind_v, prob_v = kind[idx_val], prob[idx_val]
lane = np.where(p_blend < low, 'pass', np.where(p_blend >= max(high, low), 'stop', 'person'))

def lanes_for(keep):
    d, g = keep & (y_val == 1), keep & (y_val == 0)
    return dict(n=int(keep.sum()), defects=int(d.sum()), defects_passed=int((d & (lane == 'pass')).sum()),
                good=int(g.sum()), good_stopped=int((g & (lane == 'stop')).sum()), person=int((keep & (lane == 'person')).sum()))

sure = np.isin(prob_v, [0, 1])
for name, keep in [('mono', kind_v == 'mono'), ('poly', kind_v == 'poly'), ('sure', sure), ('unsure', ~sure)]:
    print(name, lanes_for(keep))
print('TOTAL seconds', round(time.time() - T0))
print(json.dumps({"best_epoch": best_epoch, "cnn_auc": round(float(best_auc), 3), "cnn_far": round(false_alarm_at_95(y_val, p_cnn), 3), "svc_far": round(false_alarm_at_95(y_val, p_svc), 3), "blend_w": best_w, "blend_far": round(best_far, 3), "low": float(low), "high": float(high), "person_per_1000": round(1000 * float(person.mean())), "def_passed": int((auto_pass & (y_val == 1)).sum())}))
